def send_soap_request(data)
    res = send_request_cgi({
      'uri' => '/sap/bc/soap/rfc',
      'method' => 'POST',
      'data' => data,
      'authorization' => basic_auth(datastore['HttpUsername'], datastore['HttpPassword']),
      'cookie' => 'sap-usercontext=sap-language=EN&sap-client=' + datastore['CLIENT'],
      'ctype' => 'text/xml; charset=UTF-8',
      'headers' => {
        'SOAPAction' => 'urn:sap-com:document:sap:rfc:functions',
      },
      'vars_get' => {
        'sap-client' => datastore['CLIENT'],
        'sap-language' => 'EN'
      }
    })
    return res
  end

def process_pipeline(pipeline)
      return unless finished_pipeline_sync_event?(pipeline)

      # Use upsert since this code can be called more than once for the same pipeline
      ::Ci::FinishedPipelineChSyncEvent.upsert(
        {
          pipeline_id: pipeline.id,
          pipeline_finished_at: pipeline.finished_at,
          project_namespace_id: pipeline.project.project_namespace_id
        },
        unique_by: [:pipeline_id, :partition]
      )
    end

def query
          @query ||= %{descendant-or-self::text()[not(#{ignore_ancestor_query})]
          | descendant-or-self::a[
            not(contains(concat(" ", @class, " "), " gfm ")) and not(@href = "")
          ]}
        end

def initialize(model,
                     property_name:,
                     path: :"#{property_name}",
                     namespace: path.to_s.pluralize,
                     title_attribute: :name,
                     getter: :"#{property_name}_id",
                     setter: :"#{getter}=")
        @property_name = property_name
        @path = path
        @namespace = namespace
        @getter = getter
        @setter = setter
        @title_attribute = title_attribute

        super(model, current_user: nil)
      end

def _stages
    return payload_type_modules[Payload::Type::Stage] || {}
  end

def content_generator
    @content_generator ||= MiqWidget::ContentGenerator.new
  end
